    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch stays beside the morning stops, with room for every taste in the crew.",
      "must_do_id": null
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bosque de Chapultepec gives the nature lover a gentle green pause in the same loose orbit.",
      "must_do_id": null
    },
    {
      "poi_id": "p15",
      "kind": "meal",
      "must_do_id": null,
